H.background();
const w = H.W, h = H.H;
const N = Math.max(2, Math.round(P.N));    // number of molecules
const ratio = Math.max(1.01, P.ratio);     // Vf / Vi expansion ratio
const k = 1.38e-23;
// entropy increase for free (irreversible) expansion of ideal gas: dS = N k ln(Vf/Vi)
const dS = N * k * Math.log(ratio);
const bx = 60, by = 90, bw = w - 120, bh = h - 160;
H.rect(bx, by, bw, bh, { stroke: H.colors.axis, width: 2 });
const frac = 1 / ratio;                    // initial occupied fraction (left)
const barrierX = bx + bw * frac;
const prog = 0.5 - 0.5 * Math.cos(t * 0.8);   // 0..1 smooth loop
H.line(barrierX, by, barrierX, by + bh, { color: H.colors.violet, width: 2, dash: [6, 6] });
const rnd = (s) => { const x = Math.sin(s) * 43758.5453; return x - Math.floor(x); };
const tri = (val, range) => { const p = ((val % (2 * range)) + 2 * range) % (2 * range); return p < range ? p : 2 * range - p; };
for (let i = 0; i < N; i++) {
  const ax = rnd(i + 1), ay = rnd(i + 5);
  const leftW = (bw - 30) * frac;
  const fullW = (bw - 30);
  const regionW = leftW + (fullW - leftW) * prog;
  const ang = rnd(i + 11) * H.TAU, sp = 18 + 22 * rnd(i + 17);
  const px = bx + 15 + tri(ax * regionW + Math.cos(ang) * sp * t, regionW);
  const py = by + 15 + tri(ay * (bh - 30) + Math.sin(ang) * sp * t, bh - 30);
  H.circle(px, py, 4, { fill: H.color(i % 8) });
}
H.text("Second law: entropy rises   ΔS = N k ln(Vf/Vi) ≥ 0", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("N = " + N + "   Vf/Vi = " + ratio.toFixed(2) + "   ΔS = " + dS.toExponential(2) + " J/K", 24, 54, { color: H.colors.sub, size: 13 });
H.text("gas spontaneously fills the box; it never crowds back on its own", 24, h - 16, { color: H.colors.sub, size: 12 });
H.legend([{ label: "barrier (removed)", color: H.colors.violet }], w - 200, 96);
